            "45:17: " + getCheckMessage(MSG_KEY_VOID, 6, 1),
            "59:5: " + getCheckMessage(MSG_KEY, 7, 2),
        };
        verifyWithInlineConfigParser(
                getPath("InputReturnCountSwitches2.java"), expected);
    }

