            "44:42: " + getCheckMessage(MSG_KEY, 3, 1),
            "51:5: " + getCheckMessage(MSG_KEY, 2, 1),
            "59:57: " + getCheckMessage(MSG_KEY, 2, 1),
        };
        verifyWithInlineConfigParser(
                getPath("InputReturnCountLambda.java"), expected);
